<?php
/**
 * Creates /personal-injury-lawyers/savannah-ga/.
 *
 * WHY THIS PAGE. The anchor-text audit found 18 links reading "Savannah personal
 * injury attorneys" that pointed at the statewide pillar, because the Savannah
 * page did not exist. Chasing that back:
 *
 *   /practice-areas/savannah/personal-injury-lawyers/   50,500 impressions, pos 30.9
 *   /personal-injury-lawyers/charleston-sc/  (exists)    4,420 impressions
 *   query "savannah personal injury lawyer" + variants   6,110 impressions
 *
 * Google is still serving a Savannah PI URL that was culled and never replaced,
 * and it earns eleven times the impressions of the Charleston equivalent that
 * does exist. The four South Carolina cities each have a personal-injury page;
 * Savannah -- the firm's largest Georgia market -- did not.
 *
 * THE FREEZE IS LIFTED FOR THIS INSERT ONLY, through the
 * roden_location_freeze_active filter that inc/content-guardrails.php exposes for
 * exactly this purpose. Savannah is already in roden_office_city_slugs(), so this
 * is a defensible office-market page rather than a new doorway permutation; the
 * freeze exists to stop bulk permutation-building, not to make the six office
 * markets permanently unservable. Editing wp-config on production was the
 * alternative and is worse: CLAUDE.md is explicit that uncommitted production
 * changes are a scheduled deletion.
 *
 * EVERY STATUTE CITED ON THE PAGE WAS VERIFIED AGAINST PRIMARY TEXT during the
 * verification passes recorded in docs/statute-verification-tracker.md:
 * §§ 9-3-31, 9-3-33, 9-3-71, 9-3-99, 9-11-9.1, 33-7-11, 36-11-1, 36-33-5,
 * 40-6-56, 40-6-91, 40-6-315, 50-21-26, 50-21-29, 51-3-1, 51-4-2, 51-12-5.1,
 * 51-12-33. Sixteen sections, no unverified citation.
 *
 * _roden_last_reviewed IS DELIBERATELY NOT SET. Setting it publishes reviewedBy
 * and lastReviewed, asserting that a named attorney checked this page on a date.
 * None has -- it was drafted here. The attribution meta names Eric Roden, who is
 * admitted in Georgia, which is authorship rather than review. An attorney should
 * read this page and set the field; until then the schema stays honest.
 *
 * Idempotent: refuses if the slug already exists.
 *
 * Run:  ssh $H "wp --path=... eval-file -" < bin/create-savannah-pi-page.php
 *       (append ` apply` to write; default is a dry run)
 */

$APPLY = ( isset( $args[0] ) && 'apply' === $args[0] );
$P = json_decode( base64_decode( '' ), true );
if ( ! is_array( $P ) ) { echo "PAYLOAD DECODE FAILED\n"; return; }

// Refuse to create a duplicate.
$existing = get_page_by_path( 'personal-injury-lawyers/' . $P['slug'], OBJECT, 'practice_area' );
if ( $existing ) {
	echo "ALREADY EXISTS: post {$existing->ID}, status {$existing->post_status}\n";
	return;
}

// Parent must be the pillar it claims.
$parent = get_post( $P['parent'] );
if ( ! $parent || 'publish' !== $parent->post_status ) { echo "PARENT MISSING\n"; return; }
printf( "parent: %d %s\n", $parent->ID, wp_make_link_relative( get_permalink( $parent ) ) );
printf( "words: %d   faqs: %d   meta keys: %d\n",
	str_word_count( wp_strip_all_tags( $P['content'] ) ), count( $P['faqs'] ), count( $P['meta'] ) );

// Every internal link must resolve — this page must not add to the dead-link count.
$dead = 0;
if ( preg_match_all( '#href="(/[^"]*)"#', $P['content'], $m ) ) {
	foreach ( array_unique( $m[1] ) as $href ) {
		if ( ! url_to_postid( home_url( $href ) ) && '/contact/' !== $href ) {
			echo "  DEAD LINK: $href\n"; $dead++;
		}
	}
}
if ( $dead ) { echo "ABORTING — $dead dead link(s)\n"; return; }
echo "all internal links resolve\n";

if ( ! $APPLY ) { echo "\nDRY RUN — nothing written\n"; return; }

// Lift the freeze for this insert only.
$lift = function () { return false; };
add_filter( 'roden_location_freeze_active', $lift );

$id = wp_insert_post( array(
	'post_type'    => 'practice_area',
	'post_status'  => 'publish',
	'post_title'   => $P['title'],
	'post_name'    => $P['slug'],
	'post_parent'  => $P['parent'],
	'post_content' => $P['content'],
	'post_author'  => $parent->post_author,
), true );

remove_filter( 'roden_location_freeze_active', $lift );

if ( is_wp_error( $id ) ) { echo "INSERT FAILED: " . $id->get_error_message() . "\n"; return; }

foreach ( $P['meta'] as $k => $v ) { update_post_meta( $id, $k, $v ); }
update_post_meta( $id, '_roden_faqs', $P['faqs'] );

// Verify by re-reading, including that the guard did not demote it.
$post = get_post( $id );
printf( "\n--- verify ---\npost %d  status=%s  url=%s\n", $id, $post->post_status, wp_make_link_relative( get_permalink( $id ) ) );
printf( "guard demoted it: %s\n", ( 'publish' === $post->post_status ) ? 'no' : 'YES — still a draft' );
printf( "faqs stored: %d   author_attorney: %s   jurisdiction: %s\n",
	count( (array) get_post_meta( $id, '_roden_faqs', true ) ),
	get_post_meta( $id, '_roden_author_attorney', true ),
	get_post_meta( $id, '_roden_jurisdiction', true ) );
printf( "last_reviewed set: %s (expected: no)\n",
	get_post_meta( $id, '_roden_last_reviewed', true ) ? 'YES' : 'no' );
